parameters.jsCode:
const CACHE_HOURS = 24;

if (!globalThis.mondayCacheData) {
  globalThis.mondayCacheData = { cache: [], lastUpdated: 0 };
}

const cache = globalThis.mondayCacheData;
const now = Date.now();
const cacheIsValid = (now - cache.lastUpdated) < CACHE_HOURS * 3600 * 1000;

if (cache.cache.length && cacheIsValid) {
  return cache.cache.map(i => ({ json: i }));
}

const response = items[0].json;

const mondayItems = response.data.boards[0].items_page.items.map(i => ({
  ID_Venue: i.column_values?.[0]?.text?.trim() || "",
  ID_Item_Monday: i.id,
  Nombre: i.name
}));

globalThis.mondayCacheData = {
  cache: mondayItems,
  lastUpdated: now
};

return mondayItems.map(i => ({
  json: {
    ID_Venue: String(i.ID_Venue || "").trim().toLowerCase(),
    ID_Item_Monday: i.ID_Item_Monday,
    Nombre: i.Nombre
  }
}));

// ===============================
// CONFIGURACIÓN
// ===============================
const TARGET_MONTH = $input.first().json.Month;   // Enero
const TARGET_YEAR = $input.first().json.Year;

// ===============================
// FILTRO
// ===============================
const filtrados = items.filter(item => {
  const j = item.json;

  // 1️⃣ Eliminar filas basura
  if (!j["Company ID"] || j["Company ID"] === 0) return false;
  if (!j["Product"]) return false;

  // 2️⃣ Validar Month / Year existan
  if (!j.Month || !j.Year) return false;

  // 3️⃣ Comparar contra el mes/año objetivo
  return (
    Number(j.Month) === TARGET_MONTH &&
    Number(j.Year) === TARGET_YEAR
  );
});

return filtrados;

const response = items[0].json;

const settingsStr = response.data.boards[0].columns[0].settings_str;
if (!settingsStr) {
  throw new Error("❌ No se encontró settings_str en la respuesta de Monday.");
}

const settings = JSON.parse(settingsStr);
const labels = {};

for (const [index, name] of Object.entries(settings.labels)) {
  if (name?.trim()) labels[name.trim().toLowerCase()] = Number(index);
}

return [
  {
    json: {
      "tour virtual": 0,
      "my photo": 1,
      "my photo cate": 2,
      "default": 3,
      "no aplica": 5
    }
  }
];

function normalize(text) {
  return String(text || "")
    .toLowerCase()
    .trim()
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "");
}

const PRODUCT_MAP = {
  "tour virtual": 0,
  "my photo": 1,
  "my photo cate": 2,
  "default": 3,
  "no aplica": 5
};

return items.map(item => {
  const rawProduct = item.json.Product || item.json.product || "";
  const normalized = normalize(rawProduct);

  const productCode =
    PRODUCT_MAP[normalized] ??
    PRODUCT_MAP["default"];

  return {
    json: {
      ...item.json,
      product_code: productCode
    }
  };
});

const estadosCorrecciones = {
  "Estado México": "Estado de México",
  "EdoMéx": "Estado de México",
  "Edo Mex": "Estado de México",
  "Edomex": "Estado de México",
  "Estado de Méx": "Estado de México",
  "CDMX": "Ciudad de México",
  "DF": "Ciudad de México",
  "CdMx": "Ciudad de México",
  "Qro": "Querétaro",
  "Querétaro": "Querétaro",
  "Guanajuato.": "Guanajuato"
};

return $input.all().map(item => {
  const estadoOriginal = (item.json["Estado"] || "").trim();
  const estadoNormalizado =
    estadosCorrecciones[estadoOriginal] ||
    estadoOriginal ||
    "Sin estado";

  return {
    json: {
      ...item.json,
      Estado: estadoNormalizado
    }
  };
});

